from pathlib import Path
p=Path('/home/ubuntu/control-herramientas/server/db.ts'); s=p.read_text()
old='''  const latestIssueByTag = new Map<string, { condicion: string; observacion: string; fecha: number; userId: number }>();\n  for (const row of ledger) {\n    if (row.tipo === "Entrada" && row.condicion && row.condicion !== "Completa y operativa" && row.observacion) {\n      if (!latestIssueByTag.has(row.idTag)) latestIssueByTag.set(row.idTag, { condicion: row.condicion, observacion: row.observacion, fecha: row.fechaMovimiento, userId: row.userId });\n    } else if (row.tipo === "Entrada" && row.condicion === "Completa y operativa") {\n      latestIssueByTag.delete(row.idTag);\n    }\n  }'''
new='''  const latestIssueByTag = new Map<string, { condicion: string; observacion: string; fecha: number; userId: number }>();\n  const latestEntrySeen = new Set<string>();\n  for (const row of ledger) {\n    if (row.tipo === "Entrada" && !latestEntrySeen.has(row.idTag)) {\n      latestEntrySeen.add(row.idTag);\n      if (row.condicion && row.condicion !== "Completa y operativa" && row.observacion) latestIssueByTag.set(row.idTag, { condicion: row.condicion, observacion: row.observacion, fecha: row.fechaMovimiento, userId: row.userId });\n    }\n  }'''
if old not in s: raise SystemExit('ledger fallback marker not found')
s=s.replace(old,new,1); p.write_text(s)

p=Path('/home/ubuntu/control-herramientas/client/src/pages/Home.tsx'); s=p.read_text()
s=s.replace('<PageTitle title="Inventario activo" subtitle="Activos serializados: 1 Tag representa una unidad física." />','<PageTitle title="Inventario activo" subtitle="Activos serializados: 1 Tag representa una unidad física. Las observaciones no dan de baja la herramienta." /><div className="inventory-status-guide"><span className="guide-observation"><i />Observación activa: sigue en inventario, pero tiene una novedad.</span><span className="guide-retired"><i />Fuera de servicio: herramienta retirada y no disponible para préstamo.</span></div>',1)
s=s.replace('tool.observacionActiva ? "Disponible con observación" : "Disponible"','tool.observacionActiva ? "OBSERVACIÓN ACTIVA" : "Disponible"',1)
s=s.replace('<ShieldAlert size={15} />Dar de baja</button>','<ShieldAlert size={15} />Dar de baja / Fuera de servicio</button>',1)
p.write_text(s)

